{"command": "cat > /workspace/scripts/build.py <<'EOF'
"""Build the keygen module with the FT2 bridge tools."""
import sys, os, json, subprocess
sys.path.insert(0, '/workspace/scripts')
from ft2 import call, batch
import score as S

WORK = '/workspace/work'
SAMPLES = os.path.join(WORK, 'samples')

# tool instrument index (1-based) per logical voice
INSTR = {
    'LEAD': 1, 'ARPA': 2, 'ARPB': 3, 'BASS': 4, 'SUB': 5, 'KICK': 6, 'SNARE': 7,
    'HAT': 8, 'OHAT': 9, 'STAB1': 10, 'STAB2': 11, 'STAB3': 12, 'BELL': 13,
    'PLUCK': 14, 'FX': 15, 'PAD': 16,
}
# sample file, loop length, flags, volume, panning
SPEC = {
    'LEAD': ('lead', 128, 1, 58, 128),
    'ARPA': ('arpa', 256, 1, 46, 96),
    'ARPB': ('arpb', 256, 1, 34, 160),
    'BASS': ('bass', 256, 1, 56, 128),
    'SUB':  ('sub', 511, 1, 40, 128),
    'KICK': ('kick', 0, 0, 64, 128),
    'SNARE':('snare', 0, 0, 58, 128),
    'HAT':  ('hat', 0, 0, 40, 104),
    'OHAT': ('ohat', 0, 0, 40, 152),
    'STAB1':('stab', 256, 1, 40, 112),
    'STAB2':('stab', 256, 1, 40, 144),
    'STAB3':('stab', 256, 1, 40, 128),
    'BELL': ('bell', 0, 0, 46, 120),
    'PLUCK':('pluck', 0, 0, 44, 136),
    'FX':   ('crash', 0, 0, 50, 128),
    'PAD':  ('pad', 256, 1, 34, 128),
}
# clone-note base midi per voice (clone note 73 == that midi pitch)
BASE = {'LEAD': 60, 'ARPA': 48, 'ARPB': 48, 'BASS': 48, 'SUB': 36,
        'STAB1': 48, 'STAB2': 48, 'STAB3': 48, 'PAD': 48}

def clone_note(voice, midi):
    return 73 + (midi - BASE[voice])

def build(out_xm=None, out_wav=None, render=True):
    out_xm = out_xm or os.path.join(WORK, 'tune.xm')
    out_wav = out_wav or os.path.join(WORK, 'tune.wav')
    call('module_new', channels=16, name='KEYGEN')
    for voice, (fn, loop, flags, vol, pan) in SPEC.items():
        idx = INSTR[voice]
        call('instrument_set', instrument=idx, name=voice)
        call('sample_load', path=os.path.join(SAMPLES, fn + '.wav'), instrument=idx, sample=0)
        call('sample_set', instrument=idx, sample=0, name=fn, loop_start=0,
             loop_length=loop, flags=flags, volume=vol, panning=pan)
    npat = len(S.PATTERNS)
    for i in range(npat):
        call('order_set', position=i, pattern=i)
        call('pattern_set_length', pattern=i, rows=S.ROWS)
    call('song_set', bpm=150, speed=6, length=npat, loop_start=0)

    cells = []
    def put(pat, row, ch, note, vol, cut=None, inst=None, off=False):
        a = {'pattern': pat, 'row': row, 'channel': ch}
        if off:
            a['note'] = 97
        else:
            a['note'] = note
            a['instrument'] = inst
            a['volume'] = 15
            a['effect'] = 12
            a['effect_param'] = max(0, min(64, int(vol)))
            if cut is not None:
                a['effect'] = 14
                a['effect_param'] = 0xC0 + int(cut)
        cells.append({'name': 'pattern_set_cell', 'arguments': a})

    for pi, P in enumerate(S.PATTERNS):
        for b, cname in enumerate(P['chords']):
            r0 = b * 16
            tones = S.CHORDS[cname]
            # --- arpeggios
            if P['arp']:
                lvl = P['arp']
                idxs = S.ARP_IDX if (pi + b) % 2 == 0 else S.ARP_IDX2
                for i in range(16):
                    t = tones[idxs[i]]
                    put(pi, r0 + i, S.CH['ARPA'], clone_note('ARPA', t + 12),
                        20 if lvl == 1 else 27, cut=4 if lvl == 1 else None, inst=INSTR['ARPA'])
                    put(pi, r0 + i, S.CH['ARPB'], clone_note('ARPB', t),
                        12 if lvl == 1 else 17, cut=4 if lvl == 1 else None, inst=INSTR['ARPB'])
            # --- bass
            if P['drums'] or P['arp']:
                bl = S.BASSLINE[cname]
                for i, m in enumerate(bl):
                    put(pi, r0 + i * 2, S.CH['BASS'], clone_note('BASS', m), 46, inst=INSTR['BASS'])
                put(pi, r0, S.CH['SUB'], clone_note('SUB', bl[0]), 30, inst=INSTR['SUB'])
                put(pi, r0 + 8, S.CH['SUB'], clone_note('SUB', bl[4]), 26, inst=INSTR['SUB'])
            # --- pad
            if P['pad']:
                put(pi, r0, S.CH['PAD'], clone_note('PAD', tones[0] + 12), 17, inst=INSTR['PAD'])
            # --- drums
            if P['drums'] >= 1:
                for k in (0, 6, 8, 14):
                    put(pi, r0 + k, S.CH['KICK'], 73, 62, inst=INSTR['KICK'])
                for s in (4, 12):
                    put(pi, r0 + s, S.CH['SNARE'], 73, 54, inst=INSTR['SNARE'])
                for i in range(0, 16, 2):
                    put(pi, r0 + i, S.CH['HAT'], 73, 26 if i % 4 == 0 else 18, inst=INSTR['HAT'])
                if P['drums'] >= 2:
                    for i in range(1, 16, 2):
                        put(pi, r0 + i, S.CH['HAT'], 73, 11, inst=INSTR['HAT'])
                    put(pi, r0 + 14, S.CH['OHAT'], 73, 30, inst=INSTR['OHAT'])
            else:
                for k in (0, 8):
                    put(pi, r0 + k, S.CH['KICK'], 73, 50, inst=INSTR['KICK'])
            # --- chord stabs
            if P['stabs']:
                for st in (2, 6, 10, 14):
                    for vi, (vc, tn) in enumerate((('STAB1', tones[0]), ('STAB2', tones[1]), ('STAB3', tones[2]))):
                        put(pi, r0 + st, S.CH[vc], clone_note(vc, tn), 26, cut=3, inst=INSTR[vc])
            # --- bell
            if P['bell']:
                for rr, mm in ((0, 72), (6, 76), (12, 79)):
                    put(pi, r0 + rr, S.CH['BELL'], 73 + (mm - 72), 40, inst=INSTR['BELL'])
            # --- pluck accents
            if P['pluck']:
                for rr, mm in ((2, 69), (10, 72)):
                    put(pi, r0 + rr, S.CH['PLUCK'], 73 + (mm - 60), 34, inst=INSTR['PLUCK'])
            # --- lead melody
            if P['mel']:
                for (rr, mm, dur) in P['mel'][b]:
                    put(pi, r0 + rr, S.CH['LEAD'], clone_note('LEAD', mm), 50, inst=INSTR['LEAD'])
        # end of pattern: release pad + last melody note
        if P['pad']:
            put(pi, S.ROWS - 1, S.CH['PAD'], None, 0, off=True)
        if P['mel']:
            put(pi, S.ROWS - 1, S.CH['LEAD'], None, 0, off=True)
    # a crash at the start of the climax and a riser in the build
    put(6, 0, S.CH['FX'], 73, 46, inst=INSTR['FX'])
    put(4, 12, S.CH['FX'], 73, 30, inst=INSTR['FX'])

    batch(cells)
    call('module_save', path=out_xm, format='xm')
    if render:
        call('module_render', path=out_wav, rate=44100, bits=16, loops=2)
    return out_xm, out_wav

if __name__ == '__main__':
    xm, wav = build()
    print('saved', xm, wav)
